examples.template:
MonarchButton({{trigger}}) { isEditing = true }
    .sheet(isPresented: $isEditing) {
        VStack(alignment: .leading, spacing: theme.spacing.space3) {
            MonarchTextField({{fields.0.label}}, text: $owner, prompt: {{fields.0.placeholder}}, labelVisibility: .hidden)
            MonarchTextField({{fields.1.label}}, text: $label, prompt: {{fields.1.placeholder}}, labelVisibility: .hidden)
            HStack(spacing: theme.spacing.space2) {
                Spacer()
                MonarchButton({{cancel}}) { isEditing = false }
                MonarchButton({{apply}}, variant: .primary) { isEditing = false }
            }
        }
        .padding()
        .accessibilityElement(children: .contain)
        .accessibilityLabel({{label}})
        .presentationDetents([.height(250)])
    }

examples.setupTemplate:
@Environment(\.monarchTheme) private var theme
@State private var isEditing = false
@State private var owner = ""
@State private var label = ""

examples.setup:
@Environment(\.monarchTheme) private var theme
@State private var isEditing = false
@State private var owner = ""
@State private var label = ""

examples.code:
MonarchButton("Edit filters") { isEditing = true }
    .sheet(isPresented: $isEditing) {
        VStack(alignment: .leading, spacing: theme.spacing.space3) {
            MonarchTextField("Owner", text: $owner, prompt: "Owner", labelVisibility: .hidden)
            MonarchTextField("Label", text: $label, prompt: "Label", labelVisibility: .hidden)
            HStack(spacing: theme.spacing.space2) {
                Spacer()
                MonarchButton("Cancel") { isEditing = false }
                MonarchButton("Apply", variant: .primary) { isEditing = false }
            }
        }
        .padding()
        .accessibilityElement(children: .contain)
        .accessibilityLabel("Filters")
        .presentationDetents([.height(250)])
    }

ZStack {
    Text("Content behind the overlay")
        .accessibilityHidden(isShown)
    if isShown {
        VStack {
            Text("Discard the draft?").monarchTextStyle(.bodyStrong)
            MonarchButton("Discard", variant: .danger) { isShown = false }
        }
        .padding()
        .background(theme.colors.bgRaised, in: RoundedRectangle(cornerRadius: theme.radius.lg))
        .accessibilityAddTraits(.isModal)
        .accessibilityAction(.escape) { isShown = false }
    }
}
